import{J as e,n as t,ot as n,q as r}from"./chunks/framework.CF9rEaS5.js";var i=JSON.parse(`{"title":"Packet codec enforcement","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Packet codec enforcement"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/research/packet-codec-enforcement"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/research/packet-codec-enforcement"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/docs/research/packet-codec-enforcement.md"}},"headers":[],"relativePath":"research/packet-codec-enforcement.md","filePath":"research/packet-codec-enforcement.md","lastUpdated":1793234557000}`),a={name:`research/packet-codec-enforcement.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<div><h1 id="packet-codec-enforcement" tabindex="-1">Packet codec enforcement <a class="header-anchor" href="#packet-codec-enforcement" aria-label="Permalink to “Packet codec enforcement”">​</a></h1><p>Research note, 2026-10-26. Question: how to require new and edited packet definitions to support both encoding and decoding while legacy gaps are migrated.</p><h2 id="what-the-repository-already-enforces" tabindex="-1">What the repository already enforces <a class="header-anchor" href="#what-the-repository-already-enforces" aria-label="Permalink to “What the repository already enforces”">​</a></h2><ul><li><code>packages/protocol</code> packet classes extend <a href="https://github.com/JSPrismarine/JSPrismarine/blob/master/packages/protocol/src/NetworkPacket.ts" target="_blank" rel="noreferrer"><code>NetworkPacket&lt;T&gt;</code></a>, whose <code>serializePayload</code> and <code>deserializePayload</code> methods are abstract. TypeScript rejects a concrete subclass that omits either method. This already covers new and edited protocol packets at typecheck time. <a href="https://www.typescriptlang.org/docs/handbook/2/classes.html#abstract-classes-and-members" target="_blank" rel="noreferrer">TypeScript&#39;s abstract-member contract</a> documents the same enforcement mechanism.</li><li>Most server packet classes extend <a href="https://github.com/JSPrismarine/JSPrismarine/blob/master/packages/prismarine/src/network/packet/DataPacket.ts" target="_blank" rel="noreferrer"><code>DataPacket</code></a>, which gives <code>decodePayload</code> and <code>encodePayload</code> empty implementations. A subclass may therefore inherit a no-op in either direction and still typecheck. A source inventory found 170 packet classes. Sixteen payload-bearing classes are one-way; one other class has no payload fields or hooks and uses the empty-payload behavior. RakNet&#39;s <a href="https://github.com/JSPrismarine/JSPrismarine/blob/master/packages/raknet/src/protocol/Packet.ts" target="_blank" rel="noreferrer"><code>Packet</code></a> has the same no-op default design. Several RakNet classes override top-level <code>encode</code> or inherit behavior through <code>OfflinePacket</code>, so a check must account for method inheritance and overrides.</li><li>The JSDoc check <a href="https://github.com/JSPrismarine/JSPrismarine/blob/master/scripts/check-jsdoc.mts" target="_blank" rel="noreferrer"><code>scripts/check-jsdoc.mts</code></a> compares findings to a symbol-keyed baseline. It rejects new missing-doc findings, but it does not inspect changed paths; an existing baselined finding remains allowed when its source file changes.</li></ul><h2 id="enforcement-options" tabindex="-1">Enforcement options <a class="header-anchor" href="#enforcement-options" aria-label="Permalink to “Enforcement options”">​</a></h2><table tabindex="0"><thead><tr><th>Approach</th><th>Strength</th><th>Cost or limit</th></tr></thead><tbody><tr><td>Abstract codec methods on the packet base</td><td>Compile-time and unconditional; catches new classes and edits without baseline or Git state.</td><td>Making <code>DataPacket</code> or RakNet&#39;s hooks abstract immediately requires every existing concrete subclass to implement both hooks, including explicit no-ops for valid empty payloads and changes to abstract intermediate classes.</td></tr><tr><td>AST check with source fingerprints for legacy gaps</td><td>Incremental: new gaps fail, and a legacy packet fails as soon as its source changes, even after the change is committed. Reuses the repo&#39;s TypeScript-API check pattern without relying on Git history.</td><td>The baseline stores one SHA-256 per incomplete source file. The AST check proves that both hooks exist, not that they encode matching layouts. TypeScript&#39;s Compiler API supports source-file AST inspection, but the current TypeScript wiki cautions that its examples describe TypeScript 6 and earlier, while this repo uses TypeScript 7.</td></tr><tr><td>Encode/decode round-trip tests</td><td>Checks observable wire behavior and catches mismatched layouts.</td><td>By itself it does not require every packet to have such a test; fixtures and asymmetric protocol details can also make a simple round trip incomplete. Keep it as behavioral coverage alongside a compile-time or static contract.</td></tr></tbody></table><p>The TypeScript Compiler API&#39;s <a href="https://github.com/microsoft/TypeScript/wiki/Using-the-Compiler-API" target="_blank" rel="noreferrer">program and source-file model</a> is the primary-source reference for the AST option. The repository already uses <code>tsc-ts/api</code> in its JSDoc checker, avoiding a second parser dependency.</p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to “Recommendation”">​</a></h2><p>Keep <code>NetworkPacket&lt;T&gt;</code>&#39;s abstract pair as the contract for protocol packets. Use a dedicated AST checker for Prismarine and RakNet packet payloads. It fingerprints the existing one-way packet files, so any source edit removes the exemption; its update command only removes entries after those packets gain both directions. Payload-free packet classes may inherit the base&#39;s empty payload methods. Require a round-trip test when adding a packet or changing its wire layout, since method-presence checks cannot establish wire correctness.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to “Sources”">​</a></h2><ul><li><a href="https://github.com/JSPrismarine/JSPrismarine/blob/master/packages/protocol/src/NetworkPacket.ts" target="_blank" rel="noreferrer"><code>NetworkPacket.ts</code></a> — protocol codec hooks are abstract.</li><li><a href="https://github.com/JSPrismarine/JSPrismarine/blob/master/packages/prismarine/src/network/packet/DataPacket.ts" target="_blank" rel="noreferrer"><code>DataPacket.ts</code></a> — server packet codec hooks default to no-ops.</li><li><a href="https://github.com/JSPrismarine/JSPrismarine/blob/master/packages/raknet/src/protocol/Packet.ts" target="_blank" rel="noreferrer"><code>Packet.ts</code></a> — RakNet codec hooks default to no-ops; top-level encode/decode call them.</li><li><a href="https://github.com/JSPrismarine/JSPrismarine/blob/master/scripts/check-packet-codecs.mts" target="_blank" rel="noreferrer"><code>check-packet-codecs.mts</code></a> — AST check and source-fingerprinted legacy baseline.</li><li><a href="https://github.com/JSPrismarine/JSPrismarine/blob/master/scripts/check-jsdoc.mts" target="_blank" rel="noreferrer"><code>check-jsdoc.mts</code></a> — current AST check and baseline behavior.</li><li><a href="https://www.typescriptlang.org/docs/handbook/2/classes.html#abstract-classes-and-members" target="_blank" rel="noreferrer">TypeScript Handbook: abstract classes and members</a> — compile-time enforcement for missing abstract members.</li><li><a href="https://github.com/microsoft/TypeScript/wiki/Using-the-Compiler-API" target="_blank" rel="noreferrer">TypeScript Wiki: Using the Compiler API</a> — AST and type-checker APIs; its current notice says examples cover TypeScript 6 and earlier.</li></ul></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};